function normalize(text) {
  if (typeof text !== 'string') {
    return '';
  }
  var normalized = text.normalize('NFKC').toLowerCase();
  normalized = normalized.replace(/\s+/g, ' ').trim();
  return normalized;
}

files.tokenizer.js:
function tokenize(text, normalize) {
  if (typeof text !== 'string') text = String(text);
  var normalized = (typeof normalize === 'function') ? normalize(text) : text;
  var tokens = [];
  var re = /[A-Za-z0-9]+(?:'[A-Za-z0-9]+)*/g;
  var m;
  while ((m = re.exec(normalized)) !== null) {
    tokens.push(m[0]);
  }
  return tokens;
}

files.pipeline.js:
function processText(text) {
  var tokens = tokenize(text);
  var frequencies = {};
  var unique = [];
  var seen = {};
  for (var i = 0; i < tokens.length; i++) {
    var t = tokens[i];
    frequencies[t] = (Object.prototype.hasOwnProperty.call(frequencies, t)) ? frequencies[t] + 1 : 1;
    if (!Object.prototype.hasOwnProperty.call(seen, t)) {
      seen[t] = true;
      unique.push(t);
    }
  }
  return {
    text: tokens.join(' '),
    tokens: tokens,
    count: tokens.length,
    unique: unique,
    frequencies: frequencies
  };
}

